//! Measure external scans on a disposable folder generated by scripts/probes/ext-gen-folder.py.
//! cargo run --release -p cairn-core --example measure_rescan -- NEW_DATA_DIR GENERATED_FOLDER
//! The data directory must not exist. The probe briefly adds/removes one Markdown file.
use std::path::Path;
use std::time::Instant;

use cairn_core::knowledge::external::scan::{self, Scope};
use cairn_core::knowledge::mode;
use cairn_core::settings::KnowledgeMode;
use cairn_core::{CoreError, Db};

fn measure(db: &mut Db, scope: Scope) -> cairn_core::Result<f64> {
    let start = Instant::now();
    let mut plan = scan::prepare(db.conn(), scope)?.read(&mut |_| {})?;
    while plan.apply_some(db, scan::BATCH)? > 0 {}
    Ok(start.elapsed().as_secs_f64() * 1000.0)
}

fn main() -> cairn_core::Result<()> {
    let args: Vec<String> = std::env::args().collect();
    if args.len() != 3 {
        return Err(CoreError::Invalid(
            "Usage: measure_rescan NEW_DATA_DIR GENERATED_FOLDER".into(),
        ));
    }
    let data = Path::new(&args[1]);
    let root = std::path::absolute(&args[2])?;
    let mut categories: Vec<_> = std::fs::read_dir(&root)?
        .filter_map(|e| e.ok())
        .filter(|e| {
            e.path().is_dir()
                && !e.file_name().to_string_lossy().starts_with('.')
                && e.file_name() != "attachments"
        })
        .collect();
    categories.sort_by_key(|e| e.file_name());
    let category = categories
        .first()
        .ok_or_else(|| CoreError::Invalid("Generated folder has no category".into()))?;
    let rel = format!(
        "{}/Brand new note.md",
        category.file_name().to_string_lossy()
    );
    let target = root.join(&rel);
    if target.exists() {
        return Err(CoreError::Invalid("Probe target already exists".into()));
    }
    std::fs::create_dir(data)?;
    let mut db = Db::open_at(data)?;
    mode::choose_mode(&mut db, KnowledgeMode::External, root.to_str())?;
    println!("first scan: {:.1} ms", measure(&mut db, Scope::All)?);
    println!("no-op full scan: {:.1} ms", measure(&mut db, Scope::All)?);
    for (name, scope) in [
        ("watcher", Scope::Paths(vec![rel.clone()])),
        ("full", Scope::All),
    ] {
        std::fs::write(&target, "# Brand new note\n\nText.\n")?;
        println!("{name} add: {:.1} ms", measure(&mut db, scope.clone())?);
        std::fs::remove_file(&target)?;
        println!("{name} remove: {:.1} ms", measure(&mut db, scope)?);
    }
    Ok(())
}
